InnerHTML\":{\"__html\":\"work\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-param\",{\"href\":\"/en/search/synonyms/?original=param\",\"children\":[\"$\",\"em\",null,{\"children\":\"param\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"the Supreme\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-āpnoti\",{\"href\":\"/en/search/synonyms/?original=āpnoti\",\"children\":[\"$\",\"em\",null,{\"children\":\"āpnoti\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"achieves\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-pūruṣaḥ\",{\"href\":\"/en/search/synonyms/?original=pūruṣaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"pūruṣaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"a man\"}}],\".\"]}]]}]}]]]}]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",\"1091-translation,1091-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L29\",\"child-1095\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"Therefore, without being attached to the fruits of activities, one should act as a matter of duty, for by working without attachment one attains the Supreme.\"}}]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"1091-purport,1091-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L29\",\"child-1096\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The Supreme is the Personality of Godhead for the devotees, and liberation for the impersonalist. A person, therefore, acting for Kṛṣṇa, or in Kṛṣṇa consciousness, under proper guidance and without attachment to the result of the work, is certainly making progress toward the supreme goal of life. Arjuna is told that he should fight in the Battle of Kurukṣetra for the interest of Kṛṣṇa because Kṛṣṇa wanted him to fight. To be a good man or a nonviolent man is a personal attachment, but to act on behalf of the Supreme is to act without attachment for the result. That is perfect action of the highest degree, recommended by the Supreme Personality of Godhead, Śrī Kṛṣṇa.\"}}]}],[\"$\",\"$L29\",\"child-1097\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Vedic rituals, like prescribed sacrifices, are performed for purification of impious activities that were performed in the field of sense gratification. But action in Kṛṣṇa consciousness is transcendental to the reactions of good or evil work. A Kṛṣṇa conscious person has no attachment for the result but acts on behalf of Kṛṣṇa alone. He engages in all kinds of activities, but is completely nonattached.\"}}]}]]]}]\n"])self.__next_f.push([1,"31:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":